private static void enqueueBlockBreak(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, Direction direction, BlockPos pos, float refHardness, ToolAction refTool, int remaining) {
        ServerScheduler.schedule(1, () -> {
            BlockState offsetState = world.getBlockState(pos);

            float blockHardness = offsetState.getDestroySpeed(world, pos);
            if (ToolActionHelper.playerCanDestroyBlock(player, offsetState, pos, itemStack)
                    && blockHardness != -1
                    && blockHardness <= refHardness
                    && ToolActionHelper.isEffectiveOn(refTool, offsetState)) {
                if (EffectHelper.breakBlock(world, player, itemStack, pos, offsetState, true, false)) {
                    EffectHelper.sendEventToPlayer((ServerPlayer) player, 2001, pos, Block.getId(offsetState));

                    item.applyBlockBreakEffects(itemStack, world, offsetState, pos, player);

                    if (remaining > 0) {
                        enqueueBlockBreak(world, player, item, itemStack, direction, pos.relative(direction), refHardness, refTool, remaining - 1);
                    }
                }
            }
        });
    }

@SubscribeEvent
    public static void onServerTick(TickEvent.ServerTickEvent event) {
        if (event.phase != TickEvent.Phase.END) {
            return;
        }

        for (Iterator<Task> it = queue.iterator(); it.hasNext(); ) {
            Task task = it.next();
            if (task.getTick() < counter) {
                task.run();
                it.remove();
            }
        }

        counter++;
    }

@Override
	protected void removePassenger(Entity passenger)
	{
		super.removePassenger(passenger);
		if(!level().isClientSide)
			ApiUtils.addFutureServerTask(level(), () -> handleDismount(passenger));
		else
			//TODO is this still needed?
			ApiUtils.addFutureServerTask(level(), () -> handleDismount(passenger), true);
	}

public static void addFutureServerTask(Level world, Runnable task, boolean forceFuture)
	{
		LogicalSide side = world.isClientSide?LogicalSide.CLIENT: LogicalSide.SERVER;
		//TODO this sometimes causes NPEs?
		BlockableEventLoop<? super TickTask> tmp = LogicalSidedProvider.WORKQUEUE.get(side);
		if(forceFuture)
		{
			int tick;
			if(world.isClientSide)
				tick = 0;
			else
				tick = ((MinecraftServer)tmp).getTickCount();
			tmp.tell(new TickTask(tick, task));
		}
		else
			tmp.submitAsync(task);
	}

private void handleDismount(Entity passenger)
	{
		final var passengerPosition = getPassengerRidingPosition(passenger);
		passenger.teleportTo(passengerPosition.x, passengerPosition.y, passengerPosition.z);
		passenger.setDeltaMovement(getDeltaMovement());
		if(getDeltaMovement().y < 0)
		{
			passenger.fallDistance = SkylineHelper.fallDistanceFromSpeed(getDeltaMovement().y);
			passenger.setOnGround(false);
		}
		passenger.getData(IEDataAttachments.SKYHOOK_USER.get()).release();
		if(hand!=null&&passenger instanceof Player)
		{
			ItemStack held = ((Player)passenger).getItemInHand(hand);
			if(held.getItem()==Misc.SKYHOOK.asItem())
				((Player)passenger).getCooldowns().addCooldown(Misc.SKYHOOK.asItem(), 10);
		}
	}

public static boolean performPourAction(ItemStack stack, LivingEntity entity, InteractionHand hand)
    {
        if (!(entity instanceof Player player && stack.is(ModItems.FILLED_WATERSKIN))) return false;

        // Play empty sound
        if (!player.level().isClientSide)
        {
            double temperature = stack.getOrCreateTag().getDouble(FilledWaterskinItem.NBT_TEMPERATURE);
            double wetnessTemp = 0.05 * CSMath.sign(temperature == 0 ? 1 : temperature);
            // Replace or add water temp modifier
            Placement modPlacement = Placement.of(Mode.REPLACE, Order.FIRST, mod -> mod instanceof WaterTempModifier).orElse(Placement.LAST);
            Temperature.addModifier(player, new WaterTempModifier(wetnessTemp).tickRate(5), Temperature.Trait.WORLD, modPlacement);

            WorldHelper.playEntitySound(ModSounds.WATERSKIN_POUR, player, player.getSoundSource(), 2f, (float) ((Math.random() / 5) + 0.9));
        }

        consumeWaterskin(stack, player, hand);
        MinecraftForge.EVENT_BUS.post(new LivingEntityUseItemEvent.Finish(player, stack, 1, stack.getCraftingRemainingItem()));
        player.swing(hand, true);

        // spawn falling water particles
        Random rand = new Random();
        for (int i = 0; i < 6; i++)
        {
            TaskScheduler.scheduleServer(() ->
            {
                ParticleBatchMessage particleBatch = new ParticleBatchMessage(2);
                for (int p = 0; p < 10; p++)
                {
                    AABB playerBB = player.getDimensions(player.getPose()).makeBoundingBox(player.position()).inflate(0.2);
                    particleBatch.addParticle(ParticleTypes.FALLING_WATER,
                                              Mth.lerp(rand.nextFloat(), playerBB.minX, playerBB.maxX),
                                              playerBB.maxY,
                                              Mth.lerp(rand.nextFloat(), playerBB.minZ, playerBB.maxZ),
                                              0.3, 0.3, 0.3);
                }
                particleBatch.sendEntity(player);
            }, i);
        }
        player.getCooldowns().addCooldown(ModItems.FILLED_WATERSKIN, 10);
        player.getCooldowns().addCooldown(ModItems.WATERSKIN, 10);

        return true;
    }

@SubscribeEvent
    public static synchronized void runScheduledTasks(TickEvent event)
    {
        if ((event instanceof TickEvent.ServerTickEvent || event instanceof TickEvent.ClientTickEvent) && event.phase == TickEvent.Phase.START)
        {
            List<QueueEntry> schedule = event.side.isClient() ? CLIENT_SCHEDULE : SERVER_SCHEDULE;

            // Iterate through all active tasks
            if (!schedule.isEmpty())
            {
                for (int i = 0; i < schedule.size(); i++)
                {
                    QueueEntry entry = schedule.get(i);
                    int ticks = entry.time;

                    // If the task is ready to run, run it and remove it from the schedule
                    if (ticks <= 0)
                    {
                        try
                        {   entry.task.run();
                        }
                        catch (Exception e)
                        {   ColdSweat.LOGGER.error("Error while running scheduled task", e);
                            throw e;
                        }
                        schedule.remove(i);
                        i--;
                    }
                    // Otherwise, decrement the task's tick count
                    else
                    {   entry.time = ticks - 1;
                    }
                }
            }
        }
    }

@SubscribeEvent
        public static void onLivingDamage(LivingDamageEvent.Pre event) {
            var source = event.getSource().getEntity();
            var damage = event.getOriginalDamage();
            var entity = event.getEntity();

            var level = entity.level();
            var random = level.getRandom();

            if (damage >= 1) {
                for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.REFLECTIVE_NECKLACE.get())) {
                    var relic = (ReflectiveNecklaceItem) stack.getItem();

                    if (level.getRandom().nextDouble() > relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("chance").getValue())
                        continue;

                    var orbDamage = Math.clamp((float) (damage * relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("damage").getValue()), Float.MIN_VALUE, Float.MAX_VALUE);

                    var orb = new ReflectiveOrbEntity(RelicsEntities.REFLECTIVE_ORB.get(), level);

                    orb.setPiercings(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("piercing").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("piercings").getValue() : 0);
                    orb.setBounces(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("bounce").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("bounces").getValue() : 0);
                    orb.setStun(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("stun").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("stun").getValue() : 0);
                    orb.setLifetime((int) (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("lifetime").getValue() * 20));
                    orb.setFlawless(relic.getRelicData(entity, stack).isVisuallyFlawless());
                    orb.setPos(entity.getEyePosition());
                    orb.setDamage(orbDamage);
                    orb.setOwner(entity);
                    orb.setStack(stack);

                    if (source != null)
                        orb.setDeltaMovement(entity.position().subtract(source.position()).normalize().add(MathUtils.randomFloat(random) * 0.5D, 0, MathUtils.randomFloat(random) * 0.5D));
                    else
                        orb.setDeltaMovement(MathUtils.randomFloat(random) * 0.5D, 0.5D + random.nextFloat() * 0.25D, MathUtils.randomFloat(random) * 0.5D);

                    level.addFreshEntity(orb);

                    relic.getRelicData(entity, stack).getLevelingData().addExperience("reflection", "construct", orbDamage * 0.1D);

                    relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatisticData().getMetricData("total_orbs").addValue(1);
                }
            }

            if (!(event.getSource().getEntity() instanceof LivingEntity livingSource))
                return;

            var stack = EntityUtils.findEquippedCurio(livingSource, RelicsItems.REFLECTIVE_NECKLACE.get());

            if (!stack.isEmpty()) {
                var step = 0;

                for (var orb : level.getEntitiesOfClass(ReflectiveOrbEntity.class, livingSource.getBoundingBox().inflate(ORB_SEARCH_RADIUS)).stream()
                        .filter(orb -> !orb.isTargeted() && orb.getOwner() instanceof LivingEntity owner && owner.getStringUUID().equals(livingSource.getStringUUID()))
                        .sorted(Comparator.comparingInt(orb -> (int) orb.position().distanceTo(entity.position())))
                        .toList()) {

                    ServerScheduler.schedule(step++ * 2, () -> orb.setTarget(entity.position().add(0D, entity.getBbHeight(), 0D).add(entity.getKnownMovement())));
                }
            }
        }

