@Inject(method = "tick", at = @At("TAIL"))
    private void tick_TAIL_SpellEngine(BooleanSupplier shouldKeepTicking, CallbackInfo ci) {
        updateScheduledTasks();
    }

default void updateScheduledTasks() {
        if (!getImmediateTasks().isEmpty()) {
            var copyTasks = new ArrayList<>(getImmediateTasks());
            getImmediateTasks().clear();
            for (Runnable task : copyTasks) {
                task.run();
            }
        }

        var taskQueue = getScheduledTasks();
        if (taskQueue.isEmpty()) {
            return;
        }
        var currentTime = getSchedulerTime();
        var currentTasks = taskQueue.get(currentTime);
        if (currentTasks != null) {
            for (Runnable task : currentTasks) {
                task.run();
            }
            taskQueue.remove(currentTime);
        }
    }

public static BlockState setPipeActive(PipeBlockEntity<?, ?> blockEntity,
                                           BlockState state, boolean newActive, int duration) {
        if (!state.hasProperty(GTBlockStateProperties.ACTIVE) ||
                state.getValue(GTBlockStateProperties.ACTIVE) == newActive) {
            return state;
        }
        BlockState newState = state.setValue(GTBlockStateProperties.ACTIVE, newActive);
        if (blockEntity == null || blockEntity.getLevel() == null || blockEntity.isRemoved()) {
            return newState;
        }
        Level level = blockEntity.getLevel();

        level.setBlock(blockEntity.getBlockPos(), newState, Block.UPDATE_CLIENTS | Block.UPDATE_KNOWN_SHAPE);
        blockEntity.notifyBlockUpdate();
        blockEntity.setChanged();

        if (newActive && level instanceof ServerLevel serverLevel) {
            TaskHandler.enqueueServerTask(serverLevel, () -> setPipeActive(blockEntity, newState, false, -1), duration);
        }
        return newState;
    }

public static void enqueueServerTask(ServerLevel level, Runnable task, int delay) {
        synchronized (waitToAddTasks) {
            waitToAddTasks.computeIfAbsent(level.dimension(), key -> new ArrayList<>())
                    .add(new RunnableEntry(task, delay));
        }
    }

public static void onTickUpdate(ServerLevel level) {
        var key = level.dimension();
        synchronized (waitToAddTasks) {
            var list = waitToAddTasks.remove(key);
            if (list != null && !list.isEmpty()) {
                serverTasks.computeIfAbsent(key, k -> new ArrayList<>()).addAll(list);
            }
        }
        execute(serverTasks.get(key));
    }

private static void execute(List<RunnableEntry> tasks) {
        if (tasks == null || tasks.isEmpty()) return;
        var iter = tasks.iterator();
        while (iter.hasNext()) {
            var task = iter.next();
            if (task.delay <= 0) {
                try {
                    task.runnable.run();
                } catch (Exception e) {
                    GTCEu.LOGGER.error("error while schedule gregtech task", e);
                }
                iter.remove();
            } else {
                task.delay--;
            }
        }
    }

public static void onWorldUnLoad(ServerLevel level) {
        var key = level.dimension();
        serverTasks.remove(key);
        synchronized (waitToAddTasks) {
            waitToAddTasks.remove(key);
        }
    }

public static void handleCullingUpdates(long chunkPos, LongSet positions) {
        ClientTaskQueue.enqueueClientTask(1, () -> {
            Level level = Objects.requireNonNull(Minecraft.getInstance().level);
            BlockPos.MutableBlockPos blockPos = new BlockPos.MutableBlockPos();
            if (level.hasChunk(ChunkPos.getX(chunkPos), ChunkPos.getZ(chunkPos))) {
                positions.forEach(pos -> {
                    blockPos.set(pos);
                    if (level.getBlockEntity(blockPos) instanceof IFramedBlockEntity be) {
                        be.updateCulling(true, true);
                    }
                });
            }
        });
    }

public static void enqueueClientTask(long delay, Runnable task) {
        if (delay == 0) {
            Minecraft.getInstance().schedule(task);
            return;
        }

        //noinspection ConstantConditions
        long time = Minecraft.getInstance().level.getGameTime() + delay;
        tasks.add(new ClientTask(time, task));
    }

public static void onClientTick(@SuppressWarnings("unused") ClientTickEvent.Post event) {
        if (tasks.isEmpty()) {
            return;
        }

        Level level = Minecraft.getInstance().level;
        if (level == null || level.dimension() != lastDimension) {
            lastDimension = level != null ? level.dimension() : null;
            tasks.clear(); //Clear remaining tasks from the previous level

            if (level == null) {
                return;
            }
        }

        Iterator<ClientTask> it = tasks.iterator();
        while (it.hasNext()) {
            ClientTask task = it.next();
            if (level.getGameTime() >= task.time) {
                task.task.run();
                it.remove();
            }
        }
    }
